<p class="admin-intro">Quản lý quyền truy cập và khóa tài khoản khi cần. Lịch sử đơn hàng luôn được giữ lại.</p>
<section class="admin-panel"><form class="admin-filters" method="get" action="<?= e(base_url() . '/index.php') ?>"><input type="hidden" name="route" value="admin-users"><div class="admin-search"><?= icon('search') ?><input name="q" type="search" aria-label="Tìm tài khoản" value="<?= e(query('q')) ?>" placeholder="Tìm họ tên hoặc email…" maxlength="100"></div><button class="button button-outline">Tìm kiếm</button></form>
<div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Tài khoản</th><th>Đơn hàng</th><th>Quyền và trạng thái</th></tr></thead><tbody>
<?php foreach ($listing['rows'] as $row): ?><tr><td><strong><?= e($row['tenND']) ?></strong><small><?= e($row['email']) ?></small></td><td><?= e($row['orders']) ?></td><td><?php if ((int) $row['maND'] === $user['id']): ?><span class="admin-badge green">Quản trị viên · Bạn</span><?php else: ?><form class="admin-user-form" method="post" action="<?= e(url('admin-users')) ?>" data-confirm="Áp dụng quyền và trạng thái mới cho tài khoản này?"><?= csrf_field() ?><input type="hidden" name="id" value="<?= e($row['maND']) ?>"><select name="role" aria-label="Vai trò của <?= e($row['email']) ?>"><?php foreach (['User', 'Admin'] as $role): ?><option value="<?= e($role) ?>" <?= $row['tenVT'] === $role ? 'selected' : '' ?>><?= e(role_label($role)) ?></option><?php endforeach; ?></select><select name="blocked" aria-label="Trạng thái của <?= e($row['email']) ?>"><option value="0" <?= !$row['biKhoa'] ? 'selected' : '' ?>>Hoạt động</option><option value="1" <?= $row['biKhoa'] ? 'selected' : '' ?>>Đã khóa</option></select><button class="button button-small button-outline">Lưu</button></form><?php endif; ?></td></tr><?php endforeach; ?>
<?php if (!$listing['rows']): ?><tr><td colspan="3"><div class="admin-empty"><h3>Không tìm thấy tài khoản</h3><p>Thử một tên hoặc email khác.</p></div></td></tr><?php endif; ?>
</tbody></table></div><?php require ROOT_PATH . '/view/admin/pagination.php'; ?></section>
